import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import "./manageUserAccounts.css";
import AdminSidebar from "../components/AdminSideBar";
import Navbar from "../components/navbar";
import Footer from "../components/footer";

function ManageUserAccounts() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [role, setRole] = useState("");
  const [registrationNumber, setRegistrationNumber] = useState("");
  const [password, setPassword] = useState("");

  const [students, setStudents] = useState([]);
  const [supervisors, setSupervisors] = useState([]);
  const [evaluators, setEvaluators] = useState([]);

  const [viewStudents, setViewStudents] = useState(false);
  const [viewSupervisors, setViewSupervisors] = useState(false);
  const [viewEvaluators, setViewEvaluators] = useState(false);

  const [editingIndex, setEditingIndex] = useState(null);
  const [editingType, setEditingType] = useState("");

  const fetchData = async () => {
    const [sRes, supRes, eRes] = await Promise.all([
      fetch("http://localhost:5000/api/student").then((res) => res.json()),
      fetch("http://localhost:5000/api/admin").then((res) => res.json()),
      fetch("http://localhost:5000/api/evaluator").then((res) => res.json()),
    ]);
    setStudents(sRes);
    setSupervisors(supRes);
    setEvaluators(eRes);
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    const userPayload = { username: name, email, password, role };

    try {
      const userRes = await fetch("http://localhost:5000/api/user", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(userPayload),
      });

      const createdUser = await userRes.json();

      if (userRes.ok) {
        const userId = createdUser._id;

        if (role === "Student") {
          await fetch("http://localhost:5000/api/student", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              userId,
              studentName: name,
              regNo: registrationNumber,
              isGrouped: false,
            }),
          });
          setViewStudents(true);
        } else if (role === "Supervisor") {
          await fetch("http://localhost:5000/api/admin", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ userId, name }),
          });
          setViewSupervisors(true);
        } else if (role === "Evaluator") {
          await fetch("http://localhost:5000/api/evaluator", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ userId, name }),
          });
          setViewEvaluators(true);
        }

        fetchData();
      }
    } catch (err) {
      console.error("Error creating user:", err);
    }

    setName("");
    setEmail("");
    setRole("");
    setRegistrationNumber("");
    setPassword("");
  };

  const handleResetPassword = async (userId) => {
    const newPassword = prompt("Enter new password:");
    if (!newPassword || newPassword.trim() === "") {
      alert("Password cannot be empty.");
      return;
    }

    try {
      const response = await fetch(`http://localhost:5000/api/user/reset-password/${userId}`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ password: newPassword }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.message || "Failed to reset password.");
      }

      alert("Password reset successfully.");
    } catch (err) {
      console.error("Reset password error:", err);
      alert("Error: " + err.message);
    }
  };

  const handleDelete = async (userId, type, apiId) => {
    try {
      await fetch(`http://localhost:5000/api/user/${userId}`, { method: "DELETE" });
      await fetch(`http://localhost:5000/api/${type}/${apiId}`, { method: "DELETE" });
      fetchData();
      alert("User deleted successfully");
    } catch (err) {
      alert("Failed to delete user");
    }
  };

  return (
    <div className="manage-user-accounts">
      <Navbar />
      <div className="content-wrapper">
        <AdminSidebar />
        <div className="main-content">
          <h1>Manage User Accounts</h1>
          <form onSubmit={handleSubmit} className="user-form">
            <input type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="Name" required />
            <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="Email" required />
            <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Password" required />
            <select value={role} onChange={(e) => setRole(e.target.value)} required>
              <option value="">Select Role</option>
              <option value="Student">Student</option>
              <option value="Supervisor">Supervisor</option>
              <option value="Evaluator">Evaluator</option>
            </select>
            {role === "Student" && (
              <input
                type="text"
                value={registrationNumber}
                onChange={(e) => setRegistrationNumber(e.target.value)}
                placeholder="Registration Number"
                required
              />
            )}
            <button type="submit">{editingIndex !== null ? "Update" : "Submit"}</button>
          </form>

          {viewStudents && (
            <div>
              <h2>Students</h2>
              <table>
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Reg No</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {students.map((s, i) => (
                    <tr key={i}>
                      <td>{s.studentName}</td>
                      <td>{s.regNo}</td>
                      <td>
                        <button onClick={() => handleResetPassword(s.userId)}>Reset Password</button>
                        <button onClick={() => handleDelete(s.userId, "student", s._id)}>Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {viewSupervisors && (
            <div>
              <h2>Supervisors</h2>
              <table>
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {supervisors.map((s, i) => (
                    <tr key={i}>
                      <td>{s.name}</td>
                      <td>
                        <button onClick={() => handleResetPassword(s.userId)}>Reset Password</button>
                        <button onClick={() => handleDelete(s.userId, "admin", s._id)}>Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {viewEvaluators && (
            <div>
              <h2>Evaluators</h2>
              <table>
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {evaluators.map((e, i) => (
                    <tr key={i}>
                      <td>{e.name}</td>
                      <td>
                        <button onClick={() => handleResetPassword(e.userId)}>Reset Password</button>
                        <button onClick={() => handleDelete(e.userId, "evaluator", e._id)}>Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default ManageUserAccounts;
